import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createRequire} from 'node:module';
import {stockHarness} from './LSA-Enhanced-essential-fork/lsa-essential-e1-candidate/tests/stock-harness.mjs';
import {buildRequest} from './LSA-Enhanced-essential-fork/lsa-essential-e1-candidate/src/context/essentialDecision.mjs';
const out={scope:'Synthetic offline source probes. No GTA, network, real records, audio or game actions.',main:'612dd99b5a5442dd973f975a71abd91920b8a4fe',cases:[]};
const h=await stockHarness('openai');
const require=createRequire(import.meta.url);
const acorn=require('./LSA-Enhanced-essential-fork/lsa-essential-e1-candidate/tools/vendor/acorn');
const source=fs.readFileSync(new URL('./LSA-Enhanced-essential-fork/lsa-essential-e1-candidate/dist/plugins/LosSantosAliveServer/server.bundle.mjs',import.meta.url),'utf8');
const ast=acorn.parse(source,{ecmaVersion:'latest',sourceType:'module'});
function stock(name){const nodes=ast.body.filter(n=>n.type==='FunctionDeclaration'&&n.id.name===name);assert.equal(nodes.length,1);return source.slice(nodes[0].start,nodes[0].end);}
const identity=h.create('17');
h.context.syntheticListener={exists:true,pedId:'23',integrations:{policingRedefined:{detected:true,identity:{fullName:'PRIVATE_NAME_SENTINEL',birthday:'PRIVATE_BIRTHDAY_SENTINEL'},record:{wanted:true,advisoryText:'PRIVATE_WARRANT_SENTINEL'},inventory:{concealed:'PRIVATE_ITEM_SENTINEL'}}}};
const normalized=h.evaluate('ia(syntheticListener,"target")');
const body=buildRequest({model:'synthetic-model',effort:'low',systemInstruction:'Synthetic base',listener:normalized,source:'player_text',input:'Synthetic request'});
const prompt=body.input[0].content;
const markers=['PRIVATE_NAME_SENTINEL','PRIVATE_BIRTHDAY_SENTINEL','PRIVATE_WARRANT_SENTINEL','PRIVATE_ITEM_SENTINEL'];
assert.ok(markers.every(m=>prompt.includes(m)));
out.cases.push({case:'raw_listener_private_fields',privateMarkerCount:markers.filter(m=>prompt.includes(m)).length,rawIntegrationCopyPresent:prompt.includes('"raw"'),meaning:'Accepted synthetic listener integration fields survive the real stock normalizer and are serialized by the real request builder. Actual installed field availability remains provider-dependent.'});
h.evaluate('session.targetContext={pedId:"23",label:"other_npc"}; session.connection={refreshContext:ctx=>{globalThis.capturedRefresh=ctx}}; BK=()=>"synthetic_base"; qK(session,{actorContext:{pedId:"17"},targetContext:null,mode:"npc",setAsPrimarySession:false});');
const retained=h.evaluate('capturedRefresh.targetContext.pedId');assert.equal(retained,'23');
out.cases.push({case:'explicit_null_listener_reuse',previousListener:'23',requestedListener:null,refreshedListener:retained,meaning:'Real qK retains the previous target on explicit null. Prompt builder is a double; no live listener sequence is claimed.'});
h.evaluate(stock('Ba'));
h.evaluate('A.playerPedId="88"; var auditTurn=le.getTurn(bound.identity.turnId); auditTurn.listenerPedId="23"; RP(auditTurn);');
const audioStart=h.sent.find(m=>m.type==='npcAudioTurnStart');assert.equal(audioStart.listenerPedId,'88');
const created=h.evaluate('Xi({pedId:"18",listenerPedId:"23",source:Ht.SPECIAL_EVENT})');assert.equal(created.listenerPedId,'88');
out.cases.push({case:'player_only_turn_and_playback_audience',requestedListener:'23',createdTurnListener:created.listenerPedId,authorizedPlaybackListener:audioStart.listenerPedId,meaning:'Real Xi overrides listener with Ps; real RP and Ba authorize player-only audio. Network and native endpoints are synthetic.'});
const npcResult=await h.evaluate('tb({interactionId:"synthetic",speakerPedId:"17",targetPedId:"23"})');
const endResult=await h.evaluate('rb({interactionId:"synthetic"})');assert.equal(npcResult,null);assert.equal(endResult,false);
out.cases.push({case:'npc_exchange_stubs',startResult:npcResult,endResult,meaning:'Current real stock tb/rb functions do not orchestrate a conversation.'});
h.evaluate('A.activeActor={pedId:"17",roleName:"Civilian",nearbyPersonReferences:{P001:"24"}}; session.actorContext={pedId:"17",roleName:"Civilian",nearbyPersonReferences:{P001:"24"}};');
const decision={dialogue:'Synthetic reply.',command:'DO Follow P001'};
const validated=await h.runtime.host.validateDecision(decision,{actor:{pedId:'17',roleName:'Civilian',nearbyPersonReferences:{P001:'23'}}},identity);
assert.equal(validated.actionCount,1);
const resolved=h.evaluate('Ab("P001","17")');assert.equal(resolved,'24');
out.cases.push({case:'mutable_reference_map_at_validation',turnSnapshotTarget:'23',currentReferenceTarget:resolved,actionAccepted:validated.actionCount===1,meaning:'Current bridge checks current actor and resolver state, without comparing the supplied turn snapshot reference mapping. Native provider reference reassignment frequency is not characterized by this fixture.'});
const internal=buildRequest({model:'synthetic-model',effort:'low',systemInstruction:'Synthetic base',source:'npc_to_npc',internalEvent:'Synthetic NPC utterance',input:'Synthetic NPC utterance'});
assert.ok(internal.input.at(-1).content.includes('No player utterance'));
out.cases.push({case:'npc_input_request_semantics',userMessage:internal.input.at(-1).content,explicitConversationParticipants:false,meaning:'Nonplayer input uses generic internal-event wording; no speaker/audience conversation schema is present.'});
h.evaluate(stock('BK'));
h.evaluate('ET=()=>JSON.stringify(A.context.world); A.context.world={streetName:"PreviousActorStreet"};');
const borrowedWorld=JSON.parse(h.evaluate('BK({pedId:"17",world:{streetName:"CurrentActorStreet"}},null,"player")'));
assert.equal(borrowedWorld.streetName,'PreviousActorStreet');
out.cases.push({case:'global_world_in_actor_prompt',actorSuppliedStreet:'CurrentActorStreet',promptWorldStreet:borrowedWorld.streetName,meaning:'Real BK uses global A.context.world. ET is a capture double; real special-turn M4 world is separate and Xn does not propagate it into the OpenAI context. No physical wrong-street observation is claimed.'});
fs.writeFileSync(new URL('./architecture-probes.json',import.meta.url),JSON.stringify(out,null,2)+'\n');
