export const decisionSchema = Object.freeze({
  type: 'object',
  additionalProperties: false,
  required: ['dialogue', 'command'],
  properties: {
    dialogue: { type: 'string' },
    command: { type: 'string' },
  },
});

export function extractResponseText(response) {
  if (!response || response.status !== 'completed') throw new TypeError('Luna response was not completed.');
  if (response.error) throw new TypeError('Luna response contains an error.');
  let refusal = false;
  const texts = [];
  for (const item of Array.isArray(response.output) ? response.output : []) {
    if (item?.type !== 'message' || !Array.isArray(item.content)) continue;
    for (const content of item.content) {
      if (content?.type === 'refusal') refusal = true;
      if (content?.type === 'output_text' && typeof content.text === 'string') texts.push(content.text);
    }
  }
  if (refusal) throw new TypeError('Luna refused the request.');
  const text = texts.join('').trim();
  if (!text) throw new TypeError('Luna returned no decision text.');
  return text;
}

export function parseDecisionJson(raw) {
  let value;
  try { value = JSON.parse(raw); }
  catch { throw new TypeError('Luna returned invalid decision JSON.'); }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError('Luna decision must be a JSON object.');
  const keys = Object.keys(value).sort();
  if (keys.length !== 2 || keys[0] !== 'command' || keys[1] !== 'dialogue') throw new TypeError('Luna decision must contain only dialogue and command.');
  if (typeof value.dialogue !== 'string' || typeof value.command !== 'string') throw new TypeError('Luna decision fields must be strings.');
  const dialogue = value.dialogue.trim();
  const command = value.command.trim();
  if (!dialogue || dialogue.length > 1200) throw new TypeError('Luna dialogue must contain 1 to 1200 characters.');
  if (command.length > 300 || (command && (!/^DO\s+[A-Za-z]/i.test(command) || /[|\r\n]/.test(command)))) {
    throw new TypeError('Luna command must be empty or one complete DO command.');
  }
  if (/(^|\n)\s*DO\s*:?\s+[A-Za-z]/i.test(dialogue) || dialogue.includes('|')) {
    throw new TypeError('Luna dialogue contains a control command.');
  }
  return Object.freeze({ dialogue, command });
}

export function validateDecisionShape(decision) {
  return parseDecisionJson(JSON.stringify(decision));
}

export function buildRequest({ model, effort, systemInstruction, actor, listener, world, contextText, internalEvent, source, input, history = [], maxOutputTokens = 300, structuredSegments = false }) {
  const scene = [
    contextText,
    internalEvent ? `[INTERNAL EVENT TRIGGER]\n${String(internalEvent).slice(0, 12000)}\n[/INTERNAL EVENT TRIGGER]` : '',
    actor ? `CURRENT ACTOR DATA\n${JSON.stringify(actor)}` : '',
    listener ? `CURRENT LISTENER DATA\n${JSON.stringify(listener)}` : '',
    world ? `CURRENT WORLD DATA\n${JSON.stringify(world)}` : '',
  ].filter(Boolean).join('\n\n');
  const boundedHistory = history.slice(-12).map(message => ({ role: message.role, content: message.content }));
  const outputRules = structuredSegments
    ? 'Return one strict JSON object with exactly three fields in this order: mode, segments, command. mode is dialogue_only only when no action is needed; otherwise buffered_action. Each segments item contains exactly text and must be a complete short spoken phrase/sentence. command is empty or exactly one currently available Essential DO action. Never put DO commands in speech. Do not claim an action already happened. The mode is fixed and may not change; dialogue_only requires an empty final command.'
    : 'Return one JSON object with exactly two fields: dialogue and command. dialogue contains only brief spoken words for the player, never a DO command. command is empty or exactly one currently available Essential DO action. Do not chain actions. Do not invent targets, vehicles, weapons, or destinations.';
  const body = {
    model,
    store: false,
    reasoning: { effort },
    stream: false,
    max_output_tokens: maxOutputTokens,
    text: { format: { type: 'json_schema', name: structuredSegments ? 'e1_segmented_decision' : 'e1_decision', strict: true,
      schema: structuredSegments ? segmentedDecisionSchema : decisionSchema } },
    input: [
      { role: 'system', content: `${systemInstruction}\n\n[E1 OUTPUT RULES]\n${outputRules}\n\n[CURRENT REQUEST CONTEXT]\n${scene}` },
      ...boundedHistory,
      { role: 'user', content: source === 'special_event' || (source && !['player_text','player_mic'].includes(source))
        ? 'Respond to the internal event described in the system context. No player utterance was received.'
        : String(input || '').slice(0, 12_000) },
    ],
  };
  if (structuredSegments) body.stream = true;
  return body;
}

const segmentedDecisionSchema = Object.freeze({
  type: 'object', additionalProperties: false,
  required: ['mode', 'segments', 'command'],
  properties: {
    mode: { type: 'string', enum: ['dialogue_only', 'buffered_action'] },
    segments: { type: 'array', items: {
      type: 'object', additionalProperties: false, required: ['text'], properties: { text: { type: 'string' } },
    } },
    command: { type: 'string' },
  },
});

import { validateDecisionShape } from './essentialDecision.mjs';

const vehicleActions = new Set(['startdriving', 'entertargetvehicle', 'enterbackoftargetvehicle', 'enterdriverseatoftargetvehicle', 'followtargetvehicle', 'stopfollowingtargetvehicle', 'pullovertargetvehicle']);
const weaponActions = new Set(['equipweapon', 'attacktargetwithweapon', 'takeshotontarget', 'intimidatetargetwithweapon']);

export function validateStockDecision(decision, { identity, actor, parseActions, allowedActionNames, resolvePerson, resolveVehicle }) {
  const safe = validateDecisionShape(decision);
  const commands = safe.command.match(/\bDO\s*:?\s+[A-Za-z]/gi) || [];
  if (safe.command && commands.length !== 1) throw new TypeError('A turn may contain only one stock action.');
  const actions = safe.command ? parseActions(safe.command) : [];
  if (safe.command && actions.length !== 1) throw new TypeError('Essential did not recognize exactly one stock action.');
  if (actions.length > 1) throw new TypeError('A turn may contain only one stock action.');
  if (actions.length) {
    const action = actions[0];
    if (!allowedActionNames.has(action.actionName)) throw new TypeError('The action is not currently available to this actor.');
    if (action.target && action.target !== 'A' && !resolvePerson(action.target)) throw new TypeError('The action target is not in the current actor snapshot.');
    if ((vehicleActions.has(action.actionName) || /^V\d{3}$/i.test(action.parameter)) && (!/^V\d{3}$/i.test(action.parameter) || !resolveVehicle(action.parameter))) throw new TypeError('The vehicle reference is not in the current actor snapshot.');
    if (weaponActions.has(action.actionName)) {
      const listedWeapons = Array.isArray(actor?.availableWeapons) ? actor.availableWeapons : [];
      const availableContext = String(actor?.availableWeaponsContext || '').trim();
      const weapon = String(action.parameter || '').trim().toLowerCase();
      if (!weapon) throw new TypeError('The stock weapon action requires a verified weapon name.');
      const listed = listedWeapons.map(item => String(item?.name || item?.weaponName || item).trim().toLowerCase()).filter(Boolean);
      if (listed.length && !listed.includes(weapon)) throw new TypeError('The requested weapon is not listed in the current actor snapshot.');
      if (!listed.length) {
        const descriptions = [availableContext, actor?.equippedWeaponDescription, actor?.weaponDescription]
          .map(value => String(value || '').trim().toLowerCase())
          .filter(value => value && !['unknown', 'none', 'unarmed'].includes(value));
        const availability = descriptions.join(' ');
        if (!availability || /(?:available weapons:\s*none|no available weapons)/.test(availability) || !descriptions.some(description => description.replace(/^available weapons:\s*/i, '').split(/[,;\n]/).map(value => value.trim()).includes(weapon))) {
          throw new TypeError('The requested weapon is not verified by the current actor snapshot.');
        }
      }
    }
  }
  return Object.freeze({
    identityValid: true,
    decision: safe,
    actionCount: actions.length,
    actionNames: actions.map(action => action.actionName),
    internalTranscript: safe.command ? `${safe.command}|${safe.dialogue}` : safe.dialogue,
    validatedFor: Object.freeze({ ...identity }),
  });
}

export class DialogueHistory {
  #sessions = new Map();
  #maxMessages;
  #onMetric;

  constructor({ maxMessages = 12, onMetric = () => {} } = {}) {
    if (!Number.isSafeInteger(maxMessages) || maxMessages < 2) throw new TypeError('maxMessages must be at least 2.');
    this.#maxMessages = maxMessages;
    this.#onMetric = onMetric;
  }

  #key(pedId, sessionNonce) { return `${pedId}:${sessionNonce}`; }
  #get(pedId, sessionNonce) {
    const key = this.#key(pedId, sessionNonce);
    let session = this.#sessions.get(key);
    if (!session) { session = { messages: [], committedPlayerTurns: new Set(), pending: new Map() }; this.#sessions.set(key, session); }
    return session;
  }
  #identityKey(identity) { return [identity.pedId,identity.turnId,identity.generationId,identity.sessionNonce].join('\\0'); }
  #trim(session) {
    while (session.messages.length > this.#maxMessages) {
      const removed = session.messages.shift();
      if (removed.identityKey) session.committedPlayerTurns.delete(removed.identityKey);
      this.#onMetric('history_trimmed', { historySize: session.messages.length + 1, trimmed: 1 });
    }
  }

  readForSession(pedId, sessionNonce) {
    return (this.#sessions.get(this.#key(pedId, sessionNonce))?.messages || []).map(({ role, content }) => ({ role, content }));
  }

  commitPlayerInput({ identity, input }) {
    const text = String(input || '').trim().slice(0, 12_000);
    if (!text || !identity?.pedId || !identity?.turnId) return false;
    const session = this.#get(identity.pedId,identity.sessionNonce);
    const identityKey = this.#identityKey(identity);
    if (session.committedPlayerTurns.has(identityKey)) return false;
    session.messages.push({ role:'user',content:text,identityKey });
    session.committedPlayerTurns.add(identityKey);
    this.#trim(session);
    return true;
  }

  stage({ identity, spokenReply }) {
    const session = this.#get(identity.pedId,identity.sessionNonce);
    session.pending.set(identity.turnId, {
      identity: { ...identity },
      spokenReply: String(spokenReply || '').slice(0, 1200), ttsSucceeded:false,
    });
  }

  markModelAndTtsSucceeded(identity) {
    const item = this.#sessions.get(this.#key(identity.pedId, identity.sessionNonce))?.pending.get(identity.turnId);
    if (item && sameIdentity(item.identity, identity)) item.ttsSucceeded = true;
  }

  acceptPlaybackResult(result) {
    const session = this.#sessions.get(this.#key(result.pedId, result.sessionNonce));
    const item = session?.pending.get(result.turnId);
    if (!item || !sameIdentity(item.identity, result)) return false;
    if (!item.ttsSucceeded || result.playbackSucceeded !== true || result.wasInterrupted || !result.hadAudio || !result.playbackStarted) {
      session.pending.delete(result.turnId);
      return false;
    }
    session.pending.delete(result.turnId);
    session.messages.push({ role:'assistant', content:item.spokenReply });
    this.#trim(session);
    return true;
  }

  discard(identity) {
    const pending = this.#sessions.get(this.#key(identity.pedId, identity.sessionNonce))?.pending;
    return sameIdentity(pending?.get(identity.turnId)?.identity, identity) ? pending.delete(identity.turnId) : false;
  }

  clearSession(pedId, sessionNonce) { return this.#sessions.delete(this.#key(pedId, sessionNonce)); }
  clearAll() { this.#sessions.clear(); }
}

function sameIdentity(a, b) {
  return !!a && !!b && a.pedId === b.pedId && a.turnId === b.turnId && a.generationId === b.generationId && a.sessionNonce === b.sessionNonce;
}

import { observeNative } from './nativeDelivery.mjs';
import { decide } from '../openai/decide.mjs';
import { transcribePcm } from '../openai/transcribe.mjs';
import { speak } from '../openai/speak.mjs';
import { DialogueHistory } from '../memory/dialogueHistory.mjs';
import { validateDecisionShape } from '../context/essentialDecision.mjs';
import { validateStockDecision } from '../context/decisionValidator.mjs';
import { createProviderStack } from '../providers/providerStack.mjs';
import { VoiceResolver } from '../voice/voiceResolver.mjs';
import { executeProviderOperation } from '../reliability/providerExecutor.mjs';

export function createRuntime(config, { fetchImpl = globalThis.fetch, telemetry = null, providers = {} } = {}) {
  const history = new DialogueHistory({ maxMessages: config.maxHistoryMessages, onMetric: (event, data) => telemetry?.emit(event, null, null, data) });
  const connections = new Set();
  let bridge = null;
  // Construct provider implementations only for the existing E1 OpenAI route.
  // Stock Gemini keeps its native transport and does not enter this stack.
  const providerStack = config.provider === 'openai' ? createProviderStack(config, { fetchImpl, providers }) : null;
  const voiceResolver = config.provider === 'openai' ? new VoiceResolver(config) : null;
  const services = {
    config,
    providerStack,
    decide: providerStack ? options => providerStack.decide(options) : options => decide({ ...options, config, fetchImpl }),
    transcribe: providerStack ? options => providerStack.transcribe(options) : options => transcribePcm({ ...options, config, fetchImpl }),
    speak: providerStack ? options => providerStack.speak(options) : options => speak({ ...options, config, fetchImpl }),
    executeProvider: providerStack ? args => executeProviderOperation({ ...args, retryConfig: config.retry, telemetry: args.telemetry }) : null,
  };
  const runtime = {
    config, history, services, telemetry, providerStack, voiceResolver,
    validateDecisionShape,
    validateStockDecision,
    createTransport(geminiFactory) {
      if (config.provider === 'openai') {
        // The OpenAI route avoids constructing the Gemini transport and its client.
        return new OpenAITransport(runtime);
      }
      const gemini = geminiFactory();
      if (!gemini.provider) Object.defineProperty(gemini, 'provider', { value: 'gemini', configurable: true });
      return gemini;
    },
    attach(connection) { connections.add(connection); telemetry?.emit('bridge_ready', null, null, { provider: 'openai' }); },
    detach(connection) {
      connections.delete(connection);
        history.clearSession(connection.sessionIdentity?.pedId, connection.sessionIdentity?.sessionNonce);
        telemetry?.emit('bridge_disconnected', null, null, { provider: 'openai', reason: 'session_closed' });
    },
    attachBridge(value) {
      for (const name of ['isCurrent', 'routePinnedEvent', 'authorize', 'onNativeEvent', 'assertCapabilities', 'validateDecision', 'failMatchingTurn']) {
        if (typeof value?.[name] !== 'function') throw new Error(`Missing Essential lifecycle capability: ${name}`);
      }
      bridge = value;
    },
    abortTurn(identity, reason) {
      for (const connection of connections) connection.abortTurn(identity, reason);
    },
    get host() {
      if (!bridge) throw new Error('Essential E1 bridge has not been attached.');
      return bridge;
    },
    hostFor(connection) {
      if (!bridge) throw new Error('Essential E1 bridge has not been attached.');
      return {
        assertCapabilities: () => bridge.assertCapabilities(),
        isCurrent: identity => bridge.isCurrent(identity),
        validateDecision: async (decision, context, identity) => {
          const result = await bridge.validateDecision(decision, context, identity);
          if (result?.identityValid && result.actionCount) telemetry?.beginTurn(identity, context?.source || 'player_text')?.actionValidated(result.actionNames?.[0]);
          return result;
        },
        emit: event => connection.emitProviderEvent(event),
        observe: (identity, signal, onTerminal, onObserved) => observeNative(bridge, identity, signal, onTerminal, onObserved),
        authorize: identity => bridge.authorize(identity),
        failTurn: (identity, error, details) => bridge.failMatchingTurn(identity, error, details),
        log: (identity, event, details) => bridge.log?.(identity, event, details),
        telemetry,
      };
    },
  };
  return runtime;
}

import { OpenAITransport } from '../openai/openaiTransport.mjs';

export function sameIdentity(a, b) {
  return !!a && !!b && a.pedId === b.pedId && a.turnId === b.turnId &&
    a.generationId === b.generationId && a.sessionNonce === b.sessionNonce;
}

// Observe acknowledgements, never allocate or own playback. Subscribe before output.
export function observeNative(bridge, identity, signal, onTerminal, onObserved) {
  let accepted = false;
  let terminal = null;
  const waiters = new Set();
  const wake = () => { for (const resolve of [...waiters]) resolve(); };
  const remove = bridge.onNativeEvent(event => {
    if (!sameIdentity(identity, event)) return;
    onObserved?.(event);
    if (event.type === 'audio_turn_accepted') accepted = true;
    if (['audio_turn_rejected', 'playback_ended', 'interrupt', 'cancel', 'fail'].includes(event.type) && !terminal) {
      terminal = event; onTerminal?.(event);
    }
    wake();
  });
  const aborted = () => { terminal ||= { type: 'cancel', reason: 'cancelled' }; wake(); };
  signal.addEventListener('abort', aborted, { once: true });
  if (signal.aborted) aborted();
  function wait(predicate, timeoutMs) {
    return new Promise(resolve => {
      let timer;
      const check = () => {
        const result = predicate();
        if (result === undefined) return;
        clearTimeout(timer); waiters.delete(check); resolve(result);
      };
      timer = setTimeout(() => {
        waiters.delete(check); resolve({ ok: false, reason: 'native_ack_timeout' });
      }, timeoutMs);
      waiters.add(check); check();
    });
  }
  return {
    authorization: timeoutMs => wait(() => terminal ? { ok: false, reason: terminal.reason || terminal.type } :
      accepted ? { ok: true } : undefined, timeoutMs),
    completion: timeoutMs => wait(() => terminal ? { ...terminal, ok: terminal.type === 'playback_ended' &&
      terminal.reason === 'completed' && terminal.wasInterrupted === false &&
      terminal.hadAudio === true && terminal.playbackStarted === true } : undefined, timeoutMs),
    dispose() { remove(); signal.removeEventListener('abort', aborted); terminal ||= { type: 'cancel' }; wake(); },
  };
}

import { sameIdentity } from '../integration/nativeDelivery.mjs';
import { runSequentialTurn } from './runSequentialTurn.mjs';

function copySnapshot(value) {
  if (value == null) return null;
  try { return structuredClone(value); }
  catch { return JSON.parse(JSON.stringify(value)); }
}

function normalizeContextForComparison(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

export class OpenAIConnection {
  #runtime;
  #context;
  #turn = null;
  #closed = false;
  #inputStarted = false;
  #mic = [];
  #micBytes = 0;
  #micOverflow = false;
  #realtimeContext = '';
  #launched = false;
  #retired = false;
  #active = null;
  #metrics = null;
  #captureStartedAt = 0;
  #voiceProfile = null;

  constructor({ runtime, onEvent, options, diagnosticContext }) {
    this.#runtime = runtime;
    this.#context = Object.freeze({
      systemInstruction: String(options.systemInstruction || ''),
      actor: copySnapshot(options.actorContext),
      listener: copySnapshot(options.targetContext),
      world: copySnapshot(options.actorContext?.world),
      contextText: '',
      inputText: '',
    });
    this.provider = 'openai';
    this.closed = false;
    this.sessionIdentity = Object.freeze({ pedId: diagnosticContext?.pedId || '', sessionNonce: diagnosticContext?.sessionNonce ?? -1 });
  }

  beginTurn(turn) {
    this.#ensureOpen();
    if (!turn?.identity?.pedId || !turn.identity.turnId || !Number.isSafeInteger(turn.identity.generationId) || !Number.isSafeInteger(turn.identity.sessionNonce) || turn.identity.generationId < 0 || turn.identity.sessionNonce < 1 || turn.identity.pedId !== this.sessionIdentity.pedId || turn.identity.sessionNonce !== this.sessionIdentity.sessionNonce) {
      throw new TypeError('OpenAI generation requires a complete native identity.');
    }
    if (sameIdentity(this.#turn?.identity, turn.identity)) return Promise.resolve(false);
    if (this.#active && !sameIdentity(this.#active.identity, turn.identity)) this.abortTurn(this.#active.identity, 'superseded');
    const source = String(turn.source || 'player_text').toLowerCase();
    this.#metrics = this.#runtime.telemetry?.beginTurn(turn.identity, source, { inputChars: String(turn.context?.inputText || '').length }) || null;
    if (!this.#voiceProfile) {
      const voiceActor = turn.context?.actor || this.#context.actor || {};
      this.#voiceProfile = this.#runtime.voiceResolver?.resolve(turn.identity, voiceActor) || null;
      if (this.#voiceProfile) {
        this.#metrics?.event('speech_provider_selected', {
          speechProvider: this.#voiceProfile.provider,
          model: this.#voiceProfile.model,
          voice: this.#voiceProfile.voice,
        });
        this.#metrics?.event('voice_profile_assigned', {
          profileId: this.#voiceProfile.profileId,
          speechProvider: this.#voiceProfile.provider,
          model: this.#voiceProfile.model,
          voice: this.#voiceProfile.voice,
          speed: this.#voiceProfile.speed,
          assignmentVersion: this.#voiceProfile.assignmentVersion,
          selectionMode: this.#voiceProfile.selectionMode,
          gender: this.#voiceProfile.gender,
          ageBand: this.#voiceProfile.ageBand,
          matchReason: this.#voiceProfile.matchReason,
        });
      }
    }
    const internalSource = !['player_text','player_mic'].includes(source);
    const rawInput = String(turn.context?.inputText || '');
    const internalEvent = internalSource ? String(turn.context?.internalEvent || rawInput || '').trim().slice(0,12_000) : '';
    let contextText = String(turn.context?.contextText || '');
    if (internalEvent && contextText && normalizeContextForComparison(contextText) === normalizeContextForComparison(internalEvent)) contextText = '';
    this.#turn = Object.freeze({
      identity: Object.freeze({ ...turn.identity }), source,
      inputText: internalSource ? '' : rawInput,
      contextText,
      context: Object.freeze({
        systemInstruction: String(turn.context?.systemInstruction || this.#context.systemInstruction),
        actor: copySnapshot(turn.context?.actor || this.#context.actor),
        listener: copySnapshot(turn.context?.listener || this.#context.listener),
        world: copySnapshot(turn.context?.actor?.world || this.#context.world),
        contextText, internalEvent,
      }),
    });
    this.#launched = false;
    this.#retired = false;
    this.#inputStarted = false;
    this.#mic = [];
    this.#micBytes = 0;
    this.#micOverflow = false;
    this.#realtimeContext = '';
    return Promise.resolve();
  }

  sendText(text) {
    this.#ensureTurn();
    this.#metrics?.event('input_ready', { inputChars: String(this.#turn.inputText || text || '').trim().length, role: 'typed' });
    return Promise.resolve(this.#launch({ input: this.#turn.inputText || String(text || '').trim() }));
  }

  startRealtimeInput() {
    this.#ensureTurn();
    if (this.#inputStarted || this.#launched || this.#retired) return Promise.resolve(false);
    this.#inputStarted = true;
    this.#captureStartedAt = performance.now();
    this.#metrics?.event('capture_started', { sampleRate: 16_000, channels: 1 });
    this.#mic = [];
    this.#micBytes = 0;
    this.#micOverflow = false;
    return Promise.resolve(true);
  }

  sendRealtimeAudio(pcm16Mono, sampleRate = 16_000) {
    this.#ensureTurn();
    if (!this.#inputStarted) throw new Error('OpenAI PTT input was not started.');
    if (sampleRate !== 16_000) throw new Error('Essential PTT input must be 16 kHz mono PCM16.');
    if (this.#micOverflow) throw new Error('PTT input exceeded the configured limit.');
    const chunk = Buffer.from(pcm16Mono || []);
    if (chunk.length % 2) throw new Error('Essential PTT chunk ended on a partial PCM16 sample.');
    if (this.#micBytes + chunk.length > this.#runtime.config.maxMicPcmBytes) {
      this.#micOverflow = true;
      this.#metrics?.event('input_overflow', { bytes: this.#micBytes + chunk.length });
      this.#mic = [];
      this.#micBytes = 0;
      throw new Error('PTT input exceeded the configured 30-second limit.');
    }
    this.#mic.push(chunk);
    this.#micBytes += chunk.length;
    this.#metrics?.count('micChunks');
    return Promise.resolve(true);
  }

  sendRealtimeText(text) {
    this.#ensureTurn();
    const value = String(text || '').trim();
    if (!value) return Promise.resolve(false);
    if (this.#turn.contextText.includes(value)) return Promise.resolve(true);
    this.#realtimeContext = [this.#realtimeContext, value].filter(Boolean).join('\n\n').slice(0, 12_000);
    return Promise.resolve(true);
  }

  endRealtimeInput() {
    this.#ensureTurn();
    if (!this.#inputStarted) return Promise.resolve(false);
    this.#inputStarted = false;
    this.#metrics?.event('capture_stopped', { bytes: this.#micBytes, sampleRate: 16_000, durationMs: Math.max(0, performance.now() - this.#captureStartedAt) });
    if (this.#micOverflow) throw new Error('PTT input exceeded the configured limit; no truncated audio was submitted.');
    const pcm = Buffer.concat(this.#mic, this.#micBytes);
    this.#mic = [];
    this.#micBytes = 0;
    this.#metrics?.event('input_ready', { bytes: pcm.length, sampleRate: 16_000, channels: 1, role: 'microphone' });
    if (!pcm.length) throw new Error('PTT input did not contain microphone audio.');
    this.#launch({ pcm: new Uint8Array(pcm), sampleRate: 16_000 });
    return Promise.resolve(true);
  }

  refreshContext(context) {
    this.#ensureOpen();
    this.#context = Object.freeze({
      systemInstruction: String(context.systemInstruction || this.#context.systemInstruction),
      actor: copySnapshot(context.actorContext),
      listener: copySnapshot(context.targetContext),
      world: copySnapshot(context.actorContext?.world),
      contextText: '', inputText: '',
    });
  }

  detachAbort(identity, controller) {
    if (this.#active && sameIdentity(this.#active.identity, identity) && this.#active.controller === controller) this.#active.controller = null;
  }

  abortTurn(identity, reason = 'cancelled') {
    if (!sameIdentity(this.#turn?.identity, identity)) return false;
    this.#retired = true;
    this.#metrics?.event(String(reason).includes('supersed') ? 'supersession_requested' : 'cancellation_requested', { reason });
    this.#inputStarted = false;
    this.#mic = [];
    this.#micBytes = 0;
    if (!this.#active || !sameIdentity(this.#active.identity, identity)) return true;
    this.#active.cancelReason = String(reason || 'cancelled');
    this.#active.controller?.abort(new Error(this.#active.cancelReason));
    return true;
  }

  whenSettled(identity) {
    if (!this.#active || !sameIdentity(this.#active.identity, identity)) return Promise.resolve();
    return this.#active.done;
  }

  close() {
    if (this.#closed) return;
    this.#closed = true;
    this.closed = true;
    if (this.#turn) this.abortTurn(this.#turn.identity, 'session_closed');
    this.#runtime.detach(this);
  }

  matches(identity) { return sameIdentity(this.#turn?.identity, identity); }
  get source() { return this.#turn?.source || 'player_text'; }

  async emitProviderEvent(event) {
    this.#ensureOpen();
    if (!sameIdentity(this.#turn?.identity, event) || event.provider !== 'openai') return false;
    if (this.#active?.controller?.signal.aborted || !this.#runtime.host.isCurrent(event)) return false;
    return await this.#runtime.host.routePinnedEvent(Object.freeze({ ...event }));
  }

  #launch(input) {
    const turn = this.#turn;
    if (!turn) throw new Error('OpenAI generation is not bound to an Essential turn.');
    if (this.#launched || this.#retired) return false;
    this.#launched = true;
    const controller = new AbortController();
    const snapshot = {
      identity: turn.identity, source: turn.source,
      context: {
        ...turn.context,
        contextText: [turn.contextText, this.#realtimeContext].filter(Boolean).join('\n\n'),
      },
      input: turn.source === 'special_event' || !['player_text','player_mic'].includes(turn.source) ? '' : (input.input || ''),
      pcm: input.pcm || null,
      sampleRate: input.sampleRate || 16_000,
      speechProfile: this.#voiceProfile,
    };
    const state = { identity: turn.identity, controller, done: null, cancelReason: '' };
    this.#active = state;
    const run = Promise.resolve().then(async () => {
      if (controller.signal.aborted || this.#closed) {
        const reason = this.#closed ? 'disconnected' : this.#active?.cancelReason || 'cancelled';
        this.#metrics?.finish({ reason, stage: 'input', assistantCommitted: false });
        return { status: 'cancelled', terminalReason: reason };
      }
      return runSequentialTurn({
        connection: this,
        turn: { ...snapshot, controller },
        controller,
        services: this.#runtime.services,
        history: this.#runtime.history,
        host: this.#runtime.hostFor(this),
      });
    });
    state.done = run;
    // Retain only the latest job's settled promise until its successor replaces
    // it, so controller callers can still observe a very fast terminal result.
    run.then(() => {}, () => {});
    return true;
  }

  #ensureOpen() { if (this.#closed) throw new Error('OpenAI session is closed.'); }
  #ensureTurn() { this.#ensureOpen(); if (!this.#turn) throw new Error('OpenAI generation is not bound to an Essential turn.'); }
}

const PLAYER_SOURCES = new Set(['player_text', 'player_mic']);

function terminalForNativeEvent(event) {
  if (event.type === 'audio_turn_rejected') return 'native_auth_rejected';
  const reason = String(event.reason || '').toLowerCase();
  if (event.type === 'playback_ended') {
    if (event.wasInterrupted) return ['superseded', 'turn_superseded'].includes(reason) ? 'superseded' : 'playback_interrupted';
    return 'playback_error';
  }
  if (reason.includes('disconnect') || reason.includes('session_closed')) return 'disconnected';
  if (reason.includes('supersed')) return 'superseded';
  if (event.type === 'interrupt') return 'playback_interrupted';
  return 'cancelled';
}

function terminalForAbort(signal) {
  const reason = String(signal.reason?.message || signal.reason || '').toLowerCase();
  if (reason.includes('deadline') || reason.includes('timeout')) return 'provider_timeout';
  if (reason.includes('supersed')) return 'superseded';
  if (reason.includes('disconnect') || reason.includes('session_closed')) return 'disconnected';
  return 'cancelled';
}

function terminalForError(error, stage) {
  const code = String(error?.code || '').toLowerCase();
  const message = String(error?.message || '').toLowerCase();
  if (['invalid_response','incomplete_response','response_too_large'].includes(code)) return 'invalid_decision';
  if (['timeout','attempt_timeout','deadline_exceeded'].includes(code) || message.includes('deadline')) return 'provider_timeout';
  if (message.includes('refused')) return 'model_refusal';
  if (message.includes('invalid decision') || message.includes('decision must') || message.includes('decision fields') ||
      message.includes('dialogue must') || message.includes('command must') || message.includes('control command')) return 'invalid_decision';
  if (stage === 'transcribing') return 'stt_error';
  if (stage === 'model_running') return 'model_error';
  if (stage === 'decision_validation' || message.includes('decision_rejected')) return 'invalid_decision';
  if (stage === 'tts_running') return 'tts_error';
  if (stage === 'native_authorization') return 'native_auth_rejected';
  if (stage === 'playback_completion') return 'playback_error';
  if (message.includes('native_rejected') || message.includes('native_authorization')) return 'native_auth_rejected';
  return 'model_error';
}

function publicCause(error) {
  if (!error) return null;
  const cause = { name: String(error.name || 'Error').slice(0, 64) };
  if (error.code) cause.code = String(error.code).slice(0, 64);
  if (Number.isInteger(error.status) && error.status > 0) cause.httpStatus = error.status;
  return cause;
}

export async function runSequentialTurn({ connection, turn, controller = new AbortController(), services, history, host }) {
  const { identity, context, input, pcm, sampleRate } = turn;
  const source = String(turn.source || 'player_text').toLowerCase();
  const isPlayer = PLAYER_SOURCES.has(source);
  let observation;
  let state = 'bound';
  let terminalReason = '';
  let underlyingNativeCause = null;
  let authorizationRequested = false;
  let authorization;
  let retired = false;
  let endSent = false;
  let providerTimer = null;
  const metrics = host.telemetry?.beginTurn(identity, source, { inputChars: String(input || '').length, bytes: pcm?.byteLength || 0, sampleRate: sampleRate || 0 }) || null;

  const transition = next => { state = next; metrics?.stage(next); host.log?.(identity, next, { source }); };
  const chooseTerminal = reason => { if (!terminalReason) terminalReason = reason; return terminalReason; };
  const valid = () => !retired && !controller.signal.aborted && host.isCurrent(identity);
  const check = () => {
    if (valid()) return;
    if (!controller.signal.aborted && !host.isCurrent(identity)) chooseTerminal('superseded');
    throw controller.signal.reason || new Error('stale_or_cancelled');
  };
  const emit = async event => {
    check();
    if (await host.emit({ ...identity, provider: 'openai', ...event }) === false) throw new Error('native_rejected');
  };

  const workDeadlineMs = services.config.providerWorkDeadlineMs ?? services.config.turnDeadlineMs;
  const deadlineAt = performance.now() + workDeadlineMs;
  const providerWorkDone = metrics?.startSpan('provider_work', { watchdogMs: workDeadlineMs });
  providerTimer = setTimeout(() => {
    chooseTerminal('provider_timeout');
    metrics?.event('provider_deadline_fired', { stage: state, reason: 'provider_timeout' });
    controller.abort(new Error('provider_work_deadline'));
  }, workDeadlineMs);
  const abortListener = () => chooseTerminal(terminalForAbort(controller.signal));
  controller.signal.addEventListener('abort', abortListener, { once: true });
  const performProvider = (operation, provider, run, canRetry = () => true) => {
    if (!services.executeProvider) return run({ signal: controller.signal, timeoutMs: workDeadlineMs, telemetry: metrics, isActive: valid });
    return services.executeProvider({
      operation, provider, identity, signal: controller.signal, deadlineAt,
      isCurrent: () => !retired && host.isCurrent(identity), canRetry, telemetry: metrics,
      run: ({ signal, timeoutMs, telemetry, isActive, attemptId }) => {
        if (!isActive()) throw new Error('provider_attempt_inactive');
        return run({ signal, timeoutMs, telemetry, isActive, attemptId });
      },
    });
  };
  let nativeHandoffStarted = false;
  let pcmBytesTotal = 0;
  let pcmChunksTotal = 0;
  const forwardPcm = async (chunk, isActive = () => true) => {
    if (!isActive()) throw new Error('provider_attempt_inactive');
    check();
    if (endSent) throw new Error('chunk_after_end');
    if (services.config.structuredStreamingEnabled === true && services.config.earlyTtsEnabled === true &&
        pcmBytesTotal + chunk.byteLength > services.config.streamingMaxPcmBytes) {
      throw Object.assign(new Error('streaming_pcm_limit'), { code: 'streaming_pcm_limit' });
    }
    if (!nativeHandoffStarted) nativeHandoffStarted = true;
    if (!authorizationRequested) {
      authorizationRequested = true;
      transition('native_authorization');
      metrics?.count('authorizationAttempts');
      metrics?.event('native_authorization_requested', { attempts: metrics ? 1 : 0 });
      authorization = (async () => {
        if (await host.authorize(identity) !== true) throw new Error('native_authorization_rejected');
        check();
        const result = await observation.authorization(workDeadlineMs);
        check();
        if (!result.ok) throw new Error('native_authorization_rejected');
        transition('playback_streaming');
      })();
    }
    await authorization;
    check();
    await emit({ type: 'audio', chunk });
    pcmBytesTotal += chunk.byteLength;
    pcmChunksTotal += 1;
    metrics?.audioPcm(chunk.byteLength);
    check();
  };
  try {
    check();
    host.assertCapabilities();
    observation = host.observe(identity, controller.signal, event => {
      const reason = terminalForNativeEvent(event);
      if (event.type === 'playback_ended' && endSent && event.reason === 'completed' &&
          event.wasInterrupted === false && event.hadAudio === true && event.playbackStarted === true) {
        chooseTerminal('completed');
        return;
      }
      underlyingNativeCause = { nativeType: String(event.type || '').slice(0, 64), nativeReason: String(event.reason || event.type || '').slice(0, 80) };
      chooseTerminal(reason);
      if (!controller.signal.aborted) controller.abort(new Error(reason));
    }, event => {
      const map = {
        audio_turn_accepted: 'native_authorization_accepted',
        audio_turn_rejected: 'native_authorization_rejected',
        playback_started: 'native_playback_started',
        playback_ended: 'native_playback_ended',
      };
      const type = map[event.type];
      if (!type) return;
      const key = type === 'native_playback_started' ? 'playbackStartedCount' : type === 'native_playback_ended' ? 'playbackEndedCount' : type === 'native_authorization_accepted' ? 'authorizationAcceptedCount' : 'authorizationRejectedCount';
      metrics?.count(key);
      metrics?.native(type, { eventType: event.type, nativeReason: event.reason || event.type, outcome: event.wasInterrupted ? 'interrupted' : event.reason || 'accepted' });
    });

    let finalInput = input;
    if (pcm) {
      transition('transcribing');
      finalInput = await performProvider('stt', services.providerStack?.transcription.id || 'openai.transcription',
        ({ signal, timeoutMs, telemetry }) => services.transcribe({ identity, pcm, sampleRate, signal, timeoutMs, telemetry }));
      check();
      await emit({ type: 'input_transcript', text: finalInput });
      check();
    }
    if (isPlayer && !String(finalInput || '').trim()) throw new Error('player_input_empty');

    // Snapshot the old history first so the current utterance is not duplicated in
    // both the history and the current user message sent to Luna.
    const priorHistory = history.readForSession(identity.pedId, identity.sessionNonce);
    if (isPlayer) {
      const committed = history.commitPlayerInput({ identity, input: finalInput });
      metrics?.count(committed ? 'playerCommitted' : 'playerDuplicateCount');
      metrics?.event(committed ? 'player_history_committed' : 'history_duplicate_prevented', { role: 'user', inputChars: String(finalInput).length });
    }
    transition('model_running');
    let decision;
    let streamedSegments = [];
    let streamMode = null;
    let earlyAudio = null;
    if (services.config.structuredStreamingEnabled === true) {
      const allowEarlyTts = services.config.earlyTtsEnabled === true;
      const modelOptions = ({ signal, timeoutMs, telemetry }) => services.providerStack.decideStreaming({
        identity, context: { ...context, source }, source,
        input: isPlayer ? finalInput : '', history: priorHistory, signal, timeoutMs, telemetry,
      });
      if (!allowEarlyTts) {
        const result = await performProvider('model', services.providerStack.reasoning.id, modelOptions);
        decision = result.decision;
        streamMode = result.mode;
      } else {
        let queueClosed = false;
        let queueFailure = null;
        let modelFailed = false;
        const pending = [];
        let wake = null;
        const signalQueue = () => { const resume = wake; wake = null; resume?.(); };
        const enqueue = segment => {
          check();
          if (queueClosed || pending.length >= services.config.streamingMaxSegments) throw new Error('stream_segment_queue_limit');
          pending.push(segment);
          signalQueue();
        };
        const closeQueue = () => { queueClosed = true; signalQueue(); };
        const cancelQueue = error => { queueFailure = error; pending.length = 0; closeQueue(); };
        const speechTask = (async () => {
          let bytes = 0;
          let chunks = 0;
          while (true) {
            check();
            if (queueFailure) throw queueFailure;
            const segment = pending.shift();
            if (!segment) {
              if (queueClosed) break;
              await new Promise(resolve => { wake = resolve; });
              continue;
            }
            transition('tts_running');
            metrics?.event('stream_tts_segment_started', { segmentSequence: segment.sequence });
            const audio = await performProvider('tts', services.providerStack.speech.id,
              ({ signal, timeoutMs, telemetry, isActive: active }) => services.speak({
                identity, dialogue: segment.text, speechProfile: turn.speechProfile, signal, timeoutMs, telemetry,
                onPcm: chunk => forwardPcm(chunk, active),
              }), () => !nativeHandoffStarted);
            if (!audio?.bytes) throw new Error('empty_segment_audio');
            if (audio.discardedTrailingByte) throw Object.assign(new Error('partial_pcm16_sample'), { code: 'partial_pcm16_sample' });
            bytes += audio.bytes;
            chunks += audio.chunks || 0;
            metrics?.event('stream_tts_segment_finished', { segmentSequence: segment.sequence, bytes: audio.bytes, chunks: audio.chunks || 0 });
          }
          return { bytes, chunks, discardedTrailingByte: false };
        })();
        speechTask.catch(error => {
          if (!modelFailed && !controller.signal.aborted && !retired && host.isCurrent(identity)) {
            chooseTerminal('tts_error');
            controller.abort(error);
          }
        });
        const modelTask = performProvider('model', services.providerStack.reasoning.id,
          ({ signal, timeoutMs, telemetry, isActive }) => services.providerStack.decideStreaming({
            identity, context: { ...context, source }, source,
            input: isPlayer ? finalInput : '', history: priorHistory, signal, timeoutMs, telemetry,
            onSegment: async (segment, mode) => {
              if (!isActive()) throw new Error('provider_attempt_inactive');
              check();
              if (!mode) throw new Error('stream_mode_missing_before_segment');
              if (streamMode && streamMode !== mode) throw new Error('stream_mode_changed');
              streamMode = mode;
              if (mode === 'dialogue_only') {
                streamedSegments.push(segment);
                metrics?.count('segmentCount');
                enqueue(segment);
              }
            },
          }), () => streamedSegments.length === 0 && !nativeHandoffStarted);
        try {
          const result = await modelTask;
          decision = result.decision;
          streamMode = result.mode;
          closeQueue();
          // A final command is invalid in dialogue_only mode (also checked by the
          // strict decoder); the normal stock validator remains the action gate.
          earlyAudio = await speechTask;
        } catch (error) {
          modelFailed = true;
          chooseTerminal(terminalForError(error, 'model_running'));
          if (!controller.signal.aborted) controller.abort(error);
          cancelQueue(error);
          await Promise.allSettled([speechTask]);
          throw error;
        }
      }
    } else {
      decision = await performProvider('model', services.providerStack?.reasoning.id || 'openai.reasoning',
        ({ signal, timeoutMs, telemetry }) => services.decide({ identity, context: { ...context, source }, source,
          input: isPlayer ? finalInput : '', history: priorHistory, signal, timeoutMs, telemetry }));
    }
    check();
    transition('decision_validation');
    const validateSpan = metrics?.startSpan('decision_validation');
    let validated;
    try {
      validated = await host.validateDecision(decision, context, identity);
      validateSpan?.('finished');
    } catch (error) {
      validateSpan?.('failed', { code: 'invalid_decision' });
      metrics?.event('decision_rejected', { reason: 'invalid_decision' });
      throw error;
    }
    check();
    if (validated.identityValid !== true || !validated.internalTranscript) throw new Error('decision_rejected');
    transition('decision_validated');
    metrics?.event('decision_validated', { inputChars: String(decision.dialogue || '').length, attempts: validated.actionCount || 0, outcome: validated.actionCount ? 'accepted' : 'normal' });
    history.stage({ identity, spokenReply: decision.dialogue });
    metrics?.count('assistantStageCount');
    metrics?.event('assistant_history_staged', { outputChars: String(decision.dialogue || '').length });
    // Stock action listener preserves timing, including final-only actions.
    // Stock action listeners may dispatch synchronously on this transcript event.
    const hasAction = validated.actionCount > 0;
    await emit({ type: 'output_transcript', text: validated.internalTranscript });
    check();
    transition('tts_running');
    let audio = earlyAudio?.bytes > 0 ? earlyAudio : null;
    if (!audio) {
      audio = await performProvider('tts', services.providerStack?.speech.id || 'openai.speech',
        ({ signal, timeoutMs, telemetry, isActive }) => services.speak({
          identity, dialogue: decision.dialogue, speechProfile: turn.speechProfile, signal, timeoutMs, telemetry,
          onPcm: chunk => forwardPcm(chunk, isActive),
        }), () => !hasAction && !nativeHandoffStarted);
    }
    check();
    if (!authorizationRequested || !audio?.bytes || !pcmBytesTotal) throw new Error('empty_audio');
    history.markModelAndTtsSucceeded(identity);
    await emit({ type: 'generation_complete' });
    check();
    endSent = true;
    transition('stream_end');
    metrics?.count('streamEndCount');
    await emit({ type: 'turn_complete' });
    metrics?.event('native_stream_end_handoff', { accepted: true, bytes: pcmBytesTotal, chunks: pcmChunksTotal });
    providerWorkDone?.('finished');

    // The provider deadline ends once native stream completion has been sent. From
    // this point only a bounded failure watchdog remains; it never implies success.
    clearTimeout(providerTimer);
    providerTimer = null;
    transition('playback_completion');
    const expectedDurationMs = pcmBytesTotal / (24_000 * 2) * 1_000;
    const watchdogMs = Math.max(services.config.playbackCompletionMinMs ?? 60_000,
      Math.min(services.config.playbackCompletionMaxMs ?? 600_000,
        expectedDurationMs + (services.config.playbackCompletionGraceMs ?? 30_000)));
    metrics?.event('playback_watchdog_armed', { expectedDurationMs, watchdogMs });
    const result = await observation.completion(watchdogMs);
    if (!result.ok || (controller.signal.aborted && terminalReason !== 'completed')) {
      if (result.reason === 'native_ack_timeout' || !result.type) metrics?.event('playback_watchdog_fired', { watchdogMs, reason: 'native_ack_timeout' });
